type UpsertTripParams struct {
	ID                uuid.UUID
	MemberID          uuid.UUID
	ClientTripID      uuid.UUID
	VehicleID         uuid.UUID
	State             string
	StartedAt         time.Time
	EndedAt           *time.Time
	SnapshotAt        time.Time
	DurationS         *int64
	DistanceKm        *float64
	EngineDistanceKm  *float64
	MaxSpeedKmh       *float64
	AvgSpeedKmh       *float64
	MaxRpm            *int64
	HarshAccelCount   *int64
	HarshBrakeCount   *int64
	HarshStartCount   *int64
	HarshStopCount    *int64
	FuelUsedL         *float64
	FuelEconomyKmPerL *float64
	FuelCutTimeS      *float64
	IdleTimeS         *float64
	WarmUpTimeS       *float64
	AccelTimeS        *float64
	EcoSpeedTimeS     *float64
	OverSpeedTimeS    *float64
	SpeedBands        json.RawMessage
	EcoScore          *float64
	SafetyScore       *float64
	BatteryMaxV       *float64
	BatteryAvgV       *float64
	CoolantMaxC       *float64
	CoolantAvgC       *float64
	Dtc               json.RawMessage
	Simulated         bool
	App               json.RawMessage
	OverSpeedCount    *int64
	FuelCutCount      *int64
	EndReason         *string
}

type UpsertTripRow struct {
	ID       uuid.UUID
	Inserted bool
}

// Upserts a trip snapshot by (member, clientTripId). An existing trip is
// updated only while it is live, still in_progress and the new snapshot is
// newer; otherwise no row is returned and the caller reads the trip with
// GetTripByClientID to tell unchanged from trip_deleted. inserted is true
// for a new trip.
//
// updated_at (here and in the tombstone queries) is the wall clock when the
// row is written, at millisecond precision like the API, and at least 1 ms
// after the updated_at of the previous transaction that wrote the row (a
// repeat write in the same transaction, e.g. a clientTripId repeated in a
// batch, only keeps it from going back, so repeats can't push it ahead of
// the clock; nobody saw the intermediate value). now() would be the
// transaction's start: a batch that waited on the row lock behind a later
// batch would then commit newer data with an older updatedAt, and clients
// keeping the newer updatedAt would keep the stale copy.
func (q *Queries) UpsertTrip(ctx context.Context, arg UpsertTripParams) (UpsertTripRow, error) {
	row := q.db.QueryRow(ctx, upsertTrip,
		arg.ID,
		arg.MemberID,
		arg.ClientTripID,
		arg.VehicleID,
		arg.State,
		arg.StartedAt,
		arg.EndedAt,
		arg.SnapshotAt,
		arg.DurationS,
		arg.DistanceKm,
		arg.EngineDistanceKm,
		arg.MaxSpeedKmh,
		arg.AvgSpeedKmh,
		arg.MaxRpm,
		arg.HarshAccelCount,
		arg.HarshBrakeCount,
		arg.HarshStartCount,
		arg.HarshStopCount,
		arg.FuelUsedL,
		arg.FuelEconomyKmPerL,
		arg.FuelCutTimeS,
		arg.IdleTimeS,
		arg.WarmUpTimeS,
		arg.AccelTimeS,
		arg.EcoSpeedTimeS,
		arg.OverSpeedTimeS,
		arg.SpeedBands,
		arg.EcoScore,
		arg.SafetyScore,
		arg.BatteryMaxV,
		arg.BatteryAvgV,
		arg.CoolantMaxC,
		arg.CoolantAvgC,
		arg.Dtc,
		arg.Simulated,
		arg.App,
		arg.OverSpeedCount,
		arg.FuelCutCount,
		arg.EndReason,
	)
	var i UpsertTripRow
	err := row.Scan(&i.ID, &i.Inserted)
	return i, err
}
